static void aw_AtmosphereBuss_process_fast(void *aw_state, int16_t *aw_out,
    const int16_t *aw_in, int32_t sampleFrames, uint32_t aw_channels) {
    aw_AtmosphereBuss_fast_t *aw_s = (aw_AtmosphereBuss_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    float gainchase = aw_s->gainchase;
    float settingchase = aw_s->settingchase;
    float chasespeed = aw_s->chasespeed;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    float lastSampleAL = aw_s->lastSampleAL;
    float lastSampleBL = aw_s->lastSampleBL;
    float lastSampleCL = aw_s->lastSampleCL;
    float lastSampleDL = aw_s->lastSampleDL;
    float lastSampleEL = aw_s->lastSampleEL;
    float lastSampleFL = aw_s->lastSampleFL;
    float lastSampleGL = aw_s->lastSampleGL;
    float lastSampleHL = aw_s->lastSampleHL;
    float lastSampleIL = aw_s->lastSampleIL;
    float lastSampleJL = aw_s->lastSampleJL;
    float lastSampleKL = aw_s->lastSampleKL;
    float lastSampleLL = aw_s->lastSampleLL;
    float lastSampleML = aw_s->lastSampleML;
    float lastSampleAR = aw_s->lastSampleAR;
    float lastSampleBR = aw_s->lastSampleBR;
    float lastSampleCR = aw_s->lastSampleCR;
    float lastSampleDR = aw_s->lastSampleDR;
    float lastSampleER = aw_s->lastSampleER;
    float lastSampleFR = aw_s->lastSampleFR;
    float lastSampleGR = aw_s->lastSampleGR;
    float lastSampleHR = aw_s->lastSampleHR;
    float lastSampleIR = aw_s->lastSampleIR;
    float lastSampleJR = aw_s->lastSampleJR;
    float lastSampleKR = aw_s->lastSampleKR;
    float lastSampleLR = aw_s->lastSampleLR;
    float lastSampleMR = aw_s->lastSampleMR;
    float thresholdA = aw_s->thresholdA;
    float thresholdB = aw_s->thresholdB;
    float thresholdC = aw_s->thresholdC;
    float thresholdD = aw_s->thresholdD;
    float thresholdE = aw_s->thresholdE;
    float thresholdF = aw_s->thresholdF;
    float thresholdG = aw_s->thresholdG;
    float thresholdH = aw_s->thresholdH;
    float thresholdI = aw_s->thresholdI;
    float thresholdJ = aw_s->thresholdJ;
    float thresholdK = aw_s->thresholdK;
    float thresholdL = aw_s->thresholdL;
    float thresholdM = aw_s->thresholdM;
    float A = aw_s->A;
    {
	double overallscale = 1.0;
	overallscale /= 44100.0;
	overallscale *= aw_sample_rate;
	float drySampleL;
	float drySampleR;
	float inputSampleL;
	float inputSampleR;
	
	float clamp;
	double inputgain = A;
	
	if (settingchase != inputgain) {
		chasespeed *= 2.0;
		settingchase = inputgain;
	}
	if (chasespeed > 2500.0) chasespeed = 2500.0;
	if (gainchase < 0.0) gainchase = inputgain;	
	
	thresholdA = 0.618033988749894 / overallscale;
	thresholdB = 0.679837387624884 / overallscale;
	thresholdC = 0.747821126387373 / overallscale;
	thresholdD = 0.82260323902611 / overallscale;
	thresholdE = 0.904863562928721 / overallscale;
	thresholdF = 0.995349919221593 / overallscale;
	thresholdG = 1.094884911143752 / overallscale;
	thresholdH = 1.204373402258128 / overallscale;
	thresholdI = 1.32481074248394 / overallscale;
	thresholdJ = 1.457291816732335 / overallscale;
	thresholdK = 1.603020998405568 / overallscale;
	thresholdL = 1.763323098246125 / overallscale;
	thresholdM = 1.939655408070737 / overallscale;	
	
    const float aw_f_inputgain = (float)inputgain;
	while (--sampleFrames >= 0)
    {
		const float aw_inL = AW_IN_L(aw_in);
		const float aw_inR = AW_IN_R(aw_in, aw_channels);
		float aw_outL = 0.0f, aw_outR = 0.0f;/* aw:loop */
		inputSampleL = aw_inL;
		inputSampleR = aw_inR;
		
		if (fabsf(inputSampleL)<1.18e-23f) inputSampleL = fpdL * 1.18e-17f;
		if (fabsf(inputSampleR)<1.18e-23f) inputSampleR = fpdR * 1.18e-17f;
		
		chasespeed *= 0.9999f;
		chasespeed -= 0.01f;
		if (chasespeed < 350.0f) chasespeed = 350.0f;
		//we have our chase speed compensated for recent fader activity
		
		gainchase = (((gainchase*chasespeed)+aw_f_inputgain)* aw_recipf((chasespeed+1.0f)));
		//gainchase is chasing the target, as a simple multiply gain factor
		
		if (1.0f != gainchase) {
			inputSampleL *= gainchase;
			inputSampleR *= gainchase;
		}
		//done with trim control
		
		drySampleL = inputSampleL;
		drySampleR = inputSampleR;
				
		clamp = inputSampleL - lastSampleAL;
		if (clamp > thresholdA) inputSampleL = lastSampleAL + thresholdA;
		if (-clamp > thresholdA) inputSampleL = lastSampleAL - thresholdA;
		
		clamp = inputSampleL - lastSampleBL;
		if (clamp > thresholdB) inputSampleL = lastSampleBL + thresholdB;
		if (-clamp > thresholdB) inputSampleL = lastSampleBL - thresholdB;
		
		clamp = inputSampleL - lastSampleCL;
		if (clamp > thresholdC) inputSampleL = lastSampleCL + thresholdC;
		if (-clamp > thresholdC) inputSampleL = lastSampleCL - thresholdC;
		
		clamp = inputSampleL - lastSampleDL;
		if (clamp > thresholdD) inputSampleL = lastSampleDL + thresholdD;
		if (-clamp > thresholdD) inputSampleL = lastSampleDL - thresholdD;
		
		clamp = inputSampleL - lastSampleEL;
		if (clamp > thresholdE) inputSampleL = lastSampleEL + thresholdE;
		if (-clamp > thresholdE) inputSampleL = lastSampleEL - thresholdE;
		
		clamp = inputSampleL - lastSampleFL;
		if (clamp > thresholdF) inputSampleL = lastSampleFL + thresholdF;
		if (-clamp > thresholdF) inputSampleL = lastSampleFL - thresholdF;
		
		clamp = inputSampleL - lastSampleGL;
		if (clamp > thresholdG) inputSampleL = lastSampleGL + thresholdG;
		if (-clamp > thresholdG) inputSampleL = lastSampleGL - thresholdG;
		
		clamp = inputSampleL - lastSampleHL;
		if (clamp > thresholdH) inputSampleL = lastSampleHL + thresholdH;
		if (-clamp > thresholdH) inputSampleL = lastSampleHL - thresholdH;
		
		clamp = inputSampleL - lastSampleIL;
		if (clamp > thresholdI) inputSampleL = lastSampleIL + thresholdI;
		if (-clamp > thresholdI) inputSampleL = lastSampleIL - thresholdI;
		
		clamp = inputSampleL - lastSampleJL;
		if (clamp > thresholdJ) inputSampleL = lastSampleJL + thresholdJ;
		if (-clamp > thresholdJ) inputSampleL = lastSampleJL - thresholdJ;
		
		clamp = inputSampleL - lastSampleKL;
		if (clamp > thresholdK) inputSampleL = lastSampleKL + thresholdK;
		if (-clamp > thresholdK) inputSampleL = lastSampleKL - thresholdK;
		
		clamp = inputSampleL - lastSampleLL;
		if (clamp > thresholdL) inputSampleL = lastSampleLL + thresholdL;
		if (-clamp > thresholdL) inputSampleL = lastSampleLL - thresholdL;
		
		clamp = inputSampleL - lastSampleML;
		if (clamp > thresholdM) inputSampleL = lastSampleML + thresholdM;
		if (-clamp > thresholdM) inputSampleL = lastSampleML - thresholdM;
		
		
		lastSampleML = lastSampleLL;
		lastSampleLL = lastSampleKL;
		lastSampleKL = lastSampleJL;
		lastSampleJL = lastSampleIL;
		lastSampleIL = lastSampleHL;
		lastSampleHL = lastSampleGL;
		lastSampleGL = lastSampleFL;
		lastSampleFL = lastSampleEL;
		lastSampleEL = lastSampleDL;
		lastSampleDL = lastSampleCL;
		lastSampleCL = lastSampleBL;
		lastSampleBL = lastSampleAL;
		lastSampleAL = drySampleL;
		//store the raw L input sample again for use next time
		
		clamp = inputSampleR - lastSampleAR;
		if (clamp > thresholdA) inputSampleR = lastSampleAR + thresholdA;
		if (-clamp > thresholdA) inputSampleR = lastSampleAR - thresholdA;
		
		clamp = inputSampleR - lastSampleBR;
		if (clamp > thresholdB) inputSampleR = lastSampleBR + thresholdB;
		if (-clamp > thresholdB) inputSampleR = lastSampleBR - thresholdB;
		
		clamp = inputSampleR - lastSampleCR;
		if (clamp > thresholdC) inputSampleR = lastSampleCR + thresholdC;
		if (-clamp > thresholdC) inputSampleR = lastSampleCR - thresholdC;
		
		clamp = inputSampleR - lastSampleDR;
		if (clamp > thresholdD) inputSampleR = lastSampleDR + thresholdD;
		if (-clamp > thresholdD) inputSampleR = lastSampleDR - thresholdD;
		
		clamp = inputSampleR - lastSampleER;
		if (clamp > thresholdE) inputSampleR = lastSampleER + thresholdE;
		if (-clamp > thresholdE) inputSampleR = lastSampleER - thresholdE;
		
		clamp = inputSampleR - lastSampleFR;
		if (clamp > thresholdF) inputSampleR = lastSampleFR + thresholdF;
		if (-clamp > thresholdF) inputSampleR = lastSampleFR - thresholdF;
		
		clamp = inputSampleR - lastSampleGR;
		if (clamp > thresholdG) inputSampleR = lastSampleGR + thresholdG;
		if (-clamp > thresholdG) inputSampleR = lastSampleGR - thresholdG;
		
		clamp = inputSampleR - lastSampleHR;
		if (clamp > thresholdH) inputSampleR = lastSampleHR + thresholdH;
		if (-clamp > thresholdH) inputSampleR = lastSampleHR - thresholdH;
		
		clamp = inputSampleR - lastSampleIR;
		if (clamp > thresholdI) inputSampleR = lastSampleIR + thresholdI;
		if (-clamp > thresholdI) inputSampleR = lastSampleIR - thresholdI;
		
		clamp = inputSampleR - lastSampleJR;
		if (clamp > thresholdJ) inputSampleR = lastSampleJR + thresholdJ;
		if (-clamp > thresholdJ) inputSampleR = lastSampleJR - thresholdJ;
		
		clamp = inputSampleR - lastSampleKR;
		if (clamp > thresholdK) inputSampleR = lastSampleKR + thresholdK;
		if (-clamp > thresholdK) inputSampleR = lastSampleKR - thresholdK;
		
		clamp = inputSampleR - lastSampleLR;
		if (clamp > thresholdL) inputSampleR = lastSampleLR + thresholdL;
		if (-clamp > thresholdL) inputSampleR = lastSampleLR - thresholdL;
		
		clamp = inputSampleR - lastSampleMR;
		if (clamp > thresholdM) inputSampleR = lastSampleMR + thresholdM;
		if (-clamp > thresholdM) inputSampleR = lastSampleMR - thresholdM;
		
		if (inputSampleL > 1.0f) inputSampleL = 1.0f;
		if (inputSampleL < -1.0f) inputSampleL = -1.0f;
		if (inputSampleR > 1.0f) inputSampleR = 1.0f;
		if (inputSampleR < -1.0f) inputSampleR = -1.0f;
		//without this, you can get a NaN condition where it spits out DC offset at full blast!
		
		inputSampleL = asinf(inputSampleL);
		inputSampleR = asinf(inputSampleR);
		//amplitude aspect
		
		lastSampleMR = lastSampleLR;
		lastSampleLR = lastSampleKR;
		lastSampleKR = lastSampleJR;
		lastSampleJR = lastSampleIR;
		lastSampleIR = lastSampleHR;
		lastSampleHR = lastSampleGR;
		lastSampleGR = lastSampleFR;
		lastSampleFR = lastSampleER;
		lastSampleER = lastSampleDR;
		lastSampleDR = lastSampleCR;
		lastSampleCR = lastSampleBR;
		lastSampleBR = lastSampleAR;
		lastSampleAR = drySampleR;
		fpdL ^= fpdL << 13; fpdL ^= fpdL >> 17; fpdL ^= fpdL << 5;
		fpdR ^= fpdR << 13; fpdR ^= fpdR >> 17; fpdR ^= fpdR << 5;
		//end 32 bit stereo floating point dither
		
		aw_outL = inputSampleL;
		aw_outR = inputSampleR;
    /* aw:end */		AW_OUT_FAST(aw_out, aw_channels, aw_outL, aw_outR);
		aw_in += aw_channels;
		aw_out += aw_channels;
	}
}
    aw_s->gainchase = gainchase;
    aw_s->settingchase = settingchase;
    aw_s->chasespeed = chasespeed;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
    aw_s->lastSampleAL = lastSampleAL;
    aw_s->lastSampleBL = lastSampleBL;
    aw_s->lastSampleCL = lastSampleCL;
    aw_s->lastSampleDL = lastSampleDL;
    aw_s->lastSampleEL = lastSampleEL;
    aw_s->lastSampleFL = lastSampleFL;
    aw_s->lastSampleGL = lastSampleGL;
    aw_s->lastSampleHL = lastSampleHL;
    aw_s->lastSampleIL = lastSampleIL;
    aw_s->lastSampleJL = lastSampleJL;
    aw_s->lastSampleKL = lastSampleKL;
    aw_s->lastSampleLL = lastSampleLL;
    aw_s->lastSampleML = lastSampleML;
    aw_s->lastSampleAR = lastSampleAR;
    aw_s->lastSampleBR = lastSampleBR;
    aw_s->lastSampleCR = lastSampleCR;
    aw_s->lastSampleDR = lastSampleDR;
    aw_s->lastSampleER = lastSampleER;
    aw_s->lastSampleFR = lastSampleFR;
    aw_s->lastSampleGR = lastSampleGR;
    aw_s->lastSampleHR = lastSampleHR;
    aw_s->lastSampleIR = lastSampleIR;
    aw_s->lastSampleJR = lastSampleJR;
    aw_s->lastSampleKR = lastSampleKR;
    aw_s->lastSampleLR = lastSampleLR;
    aw_s->lastSampleMR = lastSampleMR;
    aw_s->thresholdA = thresholdA;
    aw_s->thresholdB = thresholdB;
    aw_s->thresholdC = thresholdC;
    aw_s->thresholdD = thresholdD;
    aw_s->thresholdE = thresholdE;
    aw_s->thresholdF = thresholdF;
    aw_s->thresholdG = thresholdG;
    aw_s->thresholdH = thresholdH;
    aw_s->thresholdI = thresholdI;
    aw_s->thresholdJ = thresholdJ;
    aw_s->thresholdK = thresholdK;
    aw_s->thresholdL = thresholdL;
    aw_s->thresholdM = thresholdM;
}

static const uint32_t aw_AtmosphereBuss_offsets_fast[] = {offsetof(aw_AtmosphereBuss_fast_t, A)};
#endif

